	return [
		"### 🧵 pi thread",
		"",
		`This conversation is stored in git on \`${ref}\`. To read it ([more](${READ_A_THREAD})):`,
		"",
		"```bash",
		...readCommands(ref, remote),
		"```",
		"",
	].join("\n");
}

